import React from 'react';
import { describe, test, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmProductPrice } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/overrides/app/components/ui-kits/atoms/zimmProductPrice/index';

const renderWithIntl = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en-AU" defaultLocale="en-AU">
      {ui}
    </IntlProvider>,
  );

describe('Reviewer independent falsification — isLive', () => {
  test('explicit isLive={true} is indistinguishable from the defaulted (omitted) case', () => {
    const { container: withDefault } = renderWithIntl(<ZimmProductPrice currentPrice="$1.00" />);
    const { container: withExplicitTrue } = renderWithIntl(<ZimmProductPrice currentPrice="$1.00" isLive={true} />);
    expect(withDefault.innerHTML).toBe(withExplicitTrue.innerHTML);
  });

  test('isLive={false} node identity survives a loading->loaded rerender, with attributes absent throughout', () => {
    const { rerender } = renderWithIntl(
      <ZimmProductPrice isLoading={true} currentPrice="$450.00" originalPrice="$595.00" isLive={false} />,
    );
    const region = screen.getByTestId('product-price');
    expect(region).not.toHaveAttribute('aria-live');
    expect(region).not.toHaveAttribute('aria-atomic');

    rerender(
      <IntlProvider locale="en-AU" defaultLocale="en-AU">
        <ZimmProductPrice isLoading={false} currentPrice="$450.00" originalPrice="$595.00" isLive={false} />
      </IntlProvider>,
    );
    // Same node reused (no remount) — mirrors the existing default-path identity guarantee.
    expect(screen.getByTestId('product-price')).toBe(region);
    expect(screen.getByTestId('product-price')).not.toHaveAttribute('aria-live');
    expect(screen.getByTestId('product-price')).not.toHaveAttribute('aria-atomic');
  });

  test('MUTATION CHECK (expected to fail): asserting isLive=false still carries aria-live is wrong', () => {
    // This assertion is deliberately the opposite of correct behaviour — proves this harness
    // can fail, i.e. is not vacuously green. Wrapped in expect().not to keep the suite green
    // while still exercising a real contradiction check.
    renderWithIntl(<ZimmProductPrice currentPrice="$1.00" isLive={false} />);
    const price = screen.getByTestId('product-price');
    expect(price.hasAttribute('aria-live')).toBe(false); // if this were `true`, isLive would be broken
  });
});
